+                                           float value) {
+                    const uint32_t storage_byte_idx = get_l2_cd_byte_idx(
+                        elem_idx * sizeof(nv_bfloat16));
+                    *reinterpret_cast<nv_bfloat16*>(
+                        static_cast<uint8_t*>(smem_cd_base) +
+                            storage_byte_idx) = __float2bfloat16_rn(value);
+                };
