+                                    final_accum[chunk_lo * 4 + 1]);
+                                write_pair(r_0, chunk_hi * 8 + col_idx * 2,
+                                    final_accum[chunk_hi * 4 + 0],
+                                    final_accum[chunk_hi * 4 + 1]);
+                            }
+                            if (valid_r1) {
