+    constexpr uint32_t kMXFP4SplitMSwapStagedBarrierIdx = kMXFP4SplitMFreeBarrierIdx + 4;
+    constexpr uint32_t kMXFP4SplitMSwapReadBarrierIdx   = kMXFP4SplitMSwapStagedBarrierIdx + 1;
