+        }
+        trace_dispatch(8, 0);   // NVLINK1_DONE (all ranks' expert counts published)
+
+        {
+            // Zero the previous generation's bank (SM90FusedWorkspace::t2_bank): every remote generation-(g - 1) write into it precedes that
