+                    if (l1_empty_target > 0) {
+                        const auto empty_ptr = workspace.get_l1_empty_count_ptr(get_ring_block_idx(pool_block_idx));
+                        if (ptx::ld_acq(empty_ptr) < l1_empty_target) {
