+                                             w_base + (static_cast<uint64_t>(n_idx / BLOCK_N) * num_k_chunks + k_block_base + k_block_idx) * SMEM_B_SIZE_PER_STAGE,
+                                             full_barriers[stage_idx], SMEM_B_SIZE_PER_STAGE, cute::TMA::CacheHintSm100::EVICT_NORMAL);
