+                            tma::copy<BLOCK_K / 2, LOAD_BLOCK_N, BLOCK_K / 2, uint8_t>(
+                                tensor_map_b_ptr, full_barriers[stage_idx], reinterpret_cast<uint8_t*>(smem_b[stage_idx]),
+                                k_idx / 2, n_idx, 1);
+                        }
