+            bool sf_pf_hit = false;
+            if constexpr (kSFProloguePrefetch) {
+                const uint32_t my_key = 1u | ((block_phase == sched::BlockPhase::Linear1 ? 1u : 0u) << 1) | (sf_n_block_idx << 2) |
