+                            decode_mxfp4_stage(stage_idx, mxfp4_buf);
+                            cutlass::arch::fence_view_async_shared();
+                            wg_bar();
+                            prof_mark(prof_decode);
+                        }
+                    }
+                    for (uint32_t k_block_idx = 0; k_block_idx < num_k_blocks; advance_pipeline(k_block_idx)) {
