+                            prof_mark(prof_wait);
+                            wg_bar();
+                            decode_mxfp4_stage(stage_idx, 0);
+                            cutlass::arch::fence_view_async_shared();
+                            wg_bar();
+                            prof_mark(prof_decode);
+                        }
+                        if constexpr (kTrace) {
