+
+        comm::grid_sync<kNumSMs, kDispatchGridSyncIndex, comm::BarrierTimeoutPolicy::TrapOnly>(
+            workspace, sm_idx, thread_idx,
+            [=]() { ptx::sync_aligned(kNumDispatchThreads, kDispatchBarrierIdx); }
