+
+        if (sm_idx == 0) {
+            {
+                // loads first, then the
+                // recv-count stores; no sum atomics -- the release flag below publishes the counts
+                constexpr uint32_t kNumPublishPerThread = math::constexpr_ceil_div(kNumExperts, kNumDispatchThreads);
