+        // 54 EPI_PUBLISHED; L2 60 EPI_CVT_DONE / 61 EPI_SCATTER_DONE (aux = pass) 62 EPI_FULL_SYNC_DONE
+        const auto trace_epi = [&](const uint32_t& event_id, const uint64_t& aux) {
