+    const at::Tensor &token_positions,
+    bool is_rope_neox_style,
+    uint32_t rope_dim,
+    const at::Tensor &cos_sin_cache,
+
+    uint32_t n_wv_group,
+    uint32_t num_per_channels,
+    bool use_tma_aligned_col_major_sf,
+    bool round_sf,
+    bool use_packed_ue8m0
