-        SM90_TMA_LOAD{},
-        make_tensor(
-            make_gmem_ptr((bf16*)params.q),
-            make_layout(
-                shape_Q_nope,
-                make_stride(params.stride_q_h_q, _1{}, params.stride_q_s_q)
-            )
-        ),
-        SmemLayoutQNoPE{}
-    );
-
-    auto shape_Q_rope = make_shape(params.h_q, D_Q-D_V, params.s_q);
-    auto tma_Q_rope = cute::make_tma_copy(
-        SM90_TMA_LOAD{},
